package com.example.webapp;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.web.bind.annotation.*;
import org.springframework.http.ResponseEntity;
import org.springframework.http.HttpHeaders;
import org.springframework.http.MediaType;
import javax.servlet.http.HttpServletRequest;
import java.util.Map;
import java.util.HashMap;
import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;

@SpringBootApplication
public class SearchApplication {
    public static void main(String[] args) {
        SpringApplication.run(SearchApplication.class, args);
    }
}

@RestController
@RequestMapping("/api/v2")
class SearchController {

    // Internal search index simulation
    private static final Map<String, String> SEARCH_INDEX = new HashMap<>() {{
        put("product1", "Widget A - Industrial Grade");
        put("product2", "Widget B - Consumer Grade");
        put("product3", "Gadget C - Premium");
    }};

    /**
     * Search endpoint that returns results as HTML fragment
     * Used by internal dashboard for AJAX-based search rendering
     */
    @GetMapping(value = "/search", produces = MediaType.TEXT_HTML_VALUE)
    public ResponseEntity<String> search(
            @RequestParam(value = "q", required = false, defaultValue = "") String query,
            @RequestParam(value = "format", required = false, defaultValue = "html") String format,
            HttpServletRequest request) {

        // Decode query parameter for display
        String decodedQuery = URLDecoder.decode(query, StandardCharsets.UTF_8);

        // Build response based on format
        StringBuilder response = new StringBuilder();

        if ("html".equals(format)) {
            response.append("<div class=\"search-results\">\n");
            response.append("  <h3>Results for: ").append(decodedQuery).append("</h3>\n");
            response.append("  <ul>\n");

            int count = 0;
            for (Map.Entry<String, String> entry : SEARCH_INDEX.entrySet()) {
                if (entry.getValue().toLowerCase().contains(decodedQuery.toLowerCase()) || decodedQuery.isEmpty()) {
                    response.append("    <li>").append(entry.getValue()).append("</li>\n");
                    count++;
                }
            }

            if (count == 0) {
                response.append("    <li class=\"no-results\">No results found for '");
                response.append(decodedQuery);
                response.append("'</li>\n");
            }

            response.append("  </ul>\n");
            response.append("</div>");
        } else {
            // JSON fallback - still vulnerable but less commonly exploited
            response.append("{\"query\": \"").append(decodedQuery).append("\", \"count\": 0}");
        }

        HttpHeaders headers = new HttpHeaders();
        headers.set("X-Request-ID", request.getHeader("X-Request-ID"));
        headers.set("Cache-Control", "no-store");
        // Note: CSP header is managed at infrastructure level

        return ResponseEntity.ok().headers(headers).body(response.toString());
    }

    /**
     * Health check endpoint for container orchestration
     */
    @GetMapping("/health")
    public ResponseEntity<Map<String, String>> health() {
        Map<String, String> status = new HashMap<>();
        status.put("status", "UP");
        status.put("version", "2.4.1");
        return ResponseEntity.ok(status);
    }

    /**
     * Error preview - renders error messages for debugging
     */
    @GetMapping(value = "/error-preview", produces = MediaType.TEXT_HTML_VALUE)
    public ResponseEntity<String> errorPreview(
            @RequestParam(value = "msg", required = false, defaultValue = "Unknown error") String message,
            @RequestParam(value = "code", required = false, defaultValue = "500") int code) {

        String html = String.format(
            "<html><body><h1>Error %d</h1><p>%s</p><a href='/'>Return home</a></body></html>",
            code, message
        );
        return ResponseEntity.status(code).body(html);
    }
}
